print(pcall(error))
print(pcall(error, nil))
print(pcall(error, {}) )
print(select('#', pcall(error)))
print(pcall(error, "msg", 0))
print(pcall(error, "msg", 1))
print(pcall(error, "msg", 2))
local function lvl2() error("deep", 2) end
local function caller() lvl2() end
print(pcall(caller))
print(pcall(function() error(setmetatable({}, {__tostring = function() return "custom" end})) end))
local ok, e = pcall(function() error({code = 42}) end)
print(ok, type(e), e.code)
print(xpcall(function() error("x") end, function(m) return "handled: " .. m end))
print(xpcall(function() return 1, 2 end, print))
print(xpcall(function(a, b) return a + b end, print, 3, 4))
print(pcall(xpcall))
print(xpcall(error, function(m) return m end, "direct"))
local res, msg = xpcall(error, error)
print(res, msg)
print(pcall(pcall))
print(pcall(function() local a; a() end))
print(pcall(function() undefinedfn() end))
print(pcall(function() local t = {} t.x.y = 1 end))
print(pcall(function() local t = {} t:nomethod() end))
print(pcall(function() return ("abc")() end))
print(pcall((function() local up = nil; return function() return up.x end end)()))
print(pcall(function() return 1 .. {} end))
print(pcall(function() local s = "a" return s .. nil end))
print(pcall(function() return nil .. "a" end))
print(pcall(function() local a = {} return a.b.c.d end))
print(pcall(function() local t = setmetatable({}, {__index = function() error("in index") end}) return t.x end))
print(pcall(function() return #5 end))
print(pcall(function() return -{} end))
print(pcall(function() local t = {} t[1] = t[1] + 1 end))
print(pcall(function() for k in pairs(nil) do end end))
print(pcall(function() for k in 5 do end end))
print(pcall(setmetatable, 1, {}))
print(pcall(setmetatable, {}, 1))
print(pcall(rawset, {}, nil, 1))
print(pcall(rawlen, 5))
print(pcall(ipairs))
print(pcall(tostring))
print(pcall(type))
print(pcall(select, "x"))
print(pcall(tonumber, "10", 99))
print(pcall(tonumber, 10, 16))
print(tonumber("ff", 16), tonumber("zz", 36), tonumber("8", 8), tonumber(" 10 ", 2), tonumber("1e1"), tonumber("0x1p4"), tonumber(""), tonumber("  "), tonumber("1 2"))
print(tonumber(nil))
print(pcall(tonumber))
print(pcall(assert, false))
print(pcall(assert, nil, "custom message"))
print(pcall(assert, false, {1}))
print(assert(1, 2, 3))
print(pcall(assert))
local function thrower() error("from thrower") end
local ok2, e2 = pcall(thrower)
print(e2)
-- error in __tostring for print
print(pcall(print, setmetatable({}, {__tostring = function() return 1 end})))
print(pcall(function() error() end))
print(pcall(error, 42))
print(pcall(error, 42, 1))
-- nested pcall
print(pcall(pcall, error, "e"))
-- error objects pass through
local et = {}
print(select(2, pcall(error, et)) == et)
-- runtime error in nested function names
local tbl = {}
function tbl.method() local z; return z.field end
print(pcall(tbl.method))
print(pcall(function() local q = 1; q.x = 2 end))
print(pcall(function() return 2^"x" end))
print(pcall(function() local x = "10"; return x + {} end))
